#!/usr/bin/env node
import { spawnSync } from 'node:child_process';
import { chmodSync, existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import path from 'node:path';

const MARKER = 'work-archive-security-hook';
const force = process.argv.includes('--force');
const repoRoot = runGit(['rev-parse', '--show-toplevel']).trim();
const gitDir = runGit(['rev-parse', '--git-dir'], repoRoot).trim();
const hooksDir = path.resolve(repoRoot, gitDir, 'hooks');

const hooks = {
  'pre-commit': `#!/usr/bin/env sh
# ${MARKER}: generated by npm run security:install-hooks
set -eu
ROOT="$(git rev-parse --show-toplevel)"
cd "$ROOT"
npm run security:secrets
`,
  'pre-push': `#!/usr/bin/env sh
# ${MARKER}: generated by npm run security:install-hooks
set -eu
ROOT="$(git rev-parse --show-toplevel)"
cd "$ROOT"
npm run security:public
`,
};

mkdirSync(hooksDir, { recursive: true });

for (const [hookName, contents] of Object.entries(hooks)) {
  const hookPath = path.join(hooksDir, hookName);
  if (existsSync(hookPath)) {
    const current = readFileSync(hookPath, 'utf8');
    if (!current.includes(MARKER) && !force) {
      throw new Error(
        `${hookName} already exists and is not managed by this repository. Re-run with --force after reviewing it.`,
      );
    }
  }

  writeFileSync(hookPath, contents, { mode: 0o755 });
  chmodSync(hookPath, 0o755);
}

console.log('Installed security git hooks: pre-commit, pre-push.');

function runGit(args, cwd = process.cwd()) {
  const result = spawnSync('git', args, {
    cwd,
    encoding: 'utf8',
    maxBuffer: 1024 * 1024,
  });

  if (result.status === 0) {
    return result.stdout;
  }

  throw new Error(
    `git ${args.join(' ')} failed: ${result.stderr.trim() || result.error?.message || 'unknown error'}`,
  );
}
